    const snap = JSON.parse(JSON.stringify(st)); snap.pk.forEach((p) => { if (p.trim) { p.max = 0; delete p.trim; } }); /* 전에 고른 조합이 줄인 구매 횟수는 새 탐색을 제한하지 않게 */
