      btn.disabled = false; $('#opt-stop').hidden = true; bar.hidden = true;
      status.innerHTML = '<div class="ovb"><i class="eb l"></i><i class="eb r"></i><i class="ar"><b></b><b></b><b></b><b></b></i><span class="ovt"><small>[계산 완료]</small>아래에서 패키지 조합을<br>선택하세요</span><i class="ar"><b></b><b></b><b></b><b></b></i></div>';
