    h += '<label>종류 <select id="gc-bt"' + (BN.bt != null ? ' disabled' : '') + '>' + GC_BT.map((b, i) => '<option value="' + i + '"' + (i === g.bt ? ' selected' : '') + '>' + b[0] + (b[1] ? ' (' + (b[1] * 100) + '%)' : '') + '</option>').join('') + '</select></label>';
    if (wish) h += '<label>위시 니케 <select id="gc-wt"><option value="">고르세요</option>' + [['일반 0.2333%', GC_POOL.std], ['필그림·오버스펙 0.1%', GC_POOL.pil]].map(([t, L]) => '<optgroup label="' + t + '">' + L.slice().sort((a, b) => a.localeCompare(b, 'ko')).map((n) => '<option' + (n === g.wt ? ' selected' : '') + '>' + esc(n) + '</option>').join('') + '</optgroup>').join('') + '</select></label>';
    h += '<label>목표 장수 <select id="gc-n">' + Array.from({ length: 11 }, (_, i) => '<option value="' + (i + 1) + '"' + (i + 1 === need ? ' selected' : '') + '>' + (i + 1) + '장</option>').join('') + '</select></label>';
    if (g.bt === 1 || g.bt === 2) h += '<label><input type="checkbox" id="gc-ev"' + (g.ev !== false ? ' checked' : '') + '> 주년 모집 혜택 이벤트</label>';
    h += '</div><p class="gcbig">이걸로 <b>' + fmt(N) + '뽑</b> 가능해요' + (N > r.base ? ' <span class="muted sm">(이벤트 보상 특뽑 ' + fmt(N - r.base) + ' 포함)</span>' : '') + '</p>';
    h += '<p class="muted">쥬얼 탭의 날짜별 예상 보유량을 씁니다. 날짜는 쥬얼 탭에서 추가할 수 있어요. D-' + r.days + '</p>';
    h += '<table class="tbl compact"><tbody>' + [['쥬얼', v.jw], ['특뽑', v.pick], ['일뽑', v.norm], ['우정뽑', v.love], ['골마 (현재 보유)', r.gold], ['실마 (현재 보유)', r.silver], ['황금몰드', r.mold.goldm], ['보라몰드', r.mold.purple], ['기업몰드 (합계)', r.mold.corp], ['퍼펙트몰드 (합계)', r.mold.perf]].map((x) => '<tr><td class="l">' + x[0] + '</td><td>' + fmt(Math.floor(x[1] || 0)) + '</td></tr>').join('') + '</tbody></table>';
    h += '<h3 class="mt">' + (wish ? '위시 니케' : '픽업') + ' 확률 <span class="muted sm">' + esc(puName() || '위시 니케를 골라 주세요') + ' · 1회 ' + (puRate() * 100).toFixed(4).replace(/0+$/, '') + '%</span></h3><p>' + (wish ? '일반 모집(일뽑 + 쥬얼 ÷ 300) ' + fmt(N) + '회' : '특뽑 ' + fmt(N) + '회 · 골마 교환 ' + ex + '회 가능') + ' → ' + need + '장 이상 확률 <b>' + gcPct(p) + '</b></p>';
    h += '<ul>' + q.map(([x, n]) => '<li>' + Math.round(x * 100) + '% 확률: ' + (n == null ? '5,000회 초과' : fmt(n) + '회') + (n != null && n > N ? ' (' + fmt(n - N) + '회 부족)' : '') + '</li>').join('') + '</ul>';
