    h += '<div class="gcbtns">' + Object.keys(GC_MOLD).map((k) => '<button type="button" data-gcm="' + k + '">' + GC_MOLD[k][0] + ' 열기</button>').join('') + '<button type="button" class="ghost" data-gc="reset">초기화</button></div>';
    h += '<div id="gc-live"></div></div>';
